    public static class SHTelemetryHelpers
    {
        // ------------------------------------------------------------------------------------
        // Definition registration
        // ------------------------------------------------------------------------------------
        // To make SimHub detect your telemetry definition, you must register the Definition file.
        //
        // This is done by creating a file:
        //   %LocalAppData%\SimHub\ExternalSims\Registrations\{DefinitionUniqueId}.simlink
        //
        // The file must contain a single line: the full path to your definition (.simdef).
        //
        // Example:
        //   SHTelemetryHelpers.RegisterDefinition("C:\\MyGame\\telemetry.simdef");
        //
        // Notes:
        // - The filename MUST match the DefinitionUniqueId
        // - The path should ideally be absolute
        // - Safe to call at every startup (recommended)
        // - The file is always rewritten to keep the path valid if the game is moved
        // ------------------------------------------------------------------------------------
        public static bool RegisterDefinition(string definitionPath, bool makeAbsolute = true)
        {
            try
            {
                if (string.IsNullOrWhiteSpace(definitionPath))
                    throw new ArgumentNullException(nameof(definitionPath));

                string finalPath = definitionPath.Trim();

                if (makeAbsolute)
                {
                    finalPath = Path.GetFullPath(finalPath);
                }

                string baseDir = Path.Combine(
                    Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),
                    "SimHub",
                    "ExternalSims",
                    "Registrations");

                Directory.CreateDirectory(baseDir);

                string linkFile = Path.Combine(
                    baseDir,
                    SHTelemetryConstants.DefinitionUniqueId + ".simlink");

                // Always rewrite → self-healing if path changed
                File.WriteAllText(linkFile, finalPath);

                Console.WriteLine($"Definition registered: {linkFile} -> {finalPath}");
                return true;
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Failed to register definition: {ex.Message}");
                return false;
            }
        }

        public static void WriteUtf8Z(byte[] dest, string value)
        {
            Array.Clear(dest, 0, dest.Length);
            if (string.IsNullOrEmpty(value)) return;

            var bytes = Encoding.UTF8.GetBytes(value);
            int n = bytes.Length;
            if (n >= dest.Length) n = dest.Length - 1; // keep room for NUL
            Buffer.BlockCopy(bytes, 0, dest, 0, n);
            dest[n] = 0;
        }

        public static ulong CreateRandomUInt64()
        {
            var b = Guid.NewGuid().ToByteArray();
            return BitConverter.ToUInt64(b, 0);
        }
    }

